-- Project: Employee work time management system
-- PostgreSQL 14+ | 24 tables with explicitly chosen referential actions
-- Intended for an EMPTY database; commands are in README.md.
-- Re-running requires deliberately dropping the work_time schema first.

BEGIN;

CREATE SCHEMA IF NOT EXISTS work_time;
SET LOCAL search_path TO work_time, public;

-- 1. Organizational structure and independent dictionaries.
CREATE TABLE "Branch" (
    "branch_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(100) NOT NULL,
    "city" VARCHAR(100) NOT NULL,
    "address" VARCHAR(200) NOT NULL
);

CREATE TABLE "Department" (
    "department_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "branch_id" INTEGER NOT NULL REFERENCES "Branch" ("branch_id"),
    "name" VARCHAR(100) NOT NULL,
    CONSTRAINT "uq_department_branch_name" UNIQUE ("branch_id", "name")
);

CREATE TABLE "Team" (
    "team_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "department_id" INTEGER NOT NULL REFERENCES "Department" ("department_id"),
    "name" VARCHAR(100) NOT NULL,
    CONSTRAINT "uq_team_department_name" UNIQUE ("department_id", "name")
);

CREATE TABLE "Position" (
    "position_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(100) NOT NULL UNIQUE,
    "description" TEXT
);

CREATE TABLE "Zone" (
    "zone_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "branch_id" INTEGER NOT NULL REFERENCES "Branch" ("branch_id"),
    "name" VARCHAR(100) NOT NULL,
    "capacity" INTEGER NOT NULL,
    CONSTRAINT "uq_zone_branch_name" UNIQUE ("branch_id", "name"),
    CONSTRAINT "ck_zone_capacity" CHECK ("capacity" > 0)
);

CREATE TABLE "ContractType" (
    "contract_type_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(100) NOT NULL UNIQUE,
    "description" TEXT
);

CREATE TABLE "AbsenceType" (
    "absence_type_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name" VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE "DayOff" (
    "day_off_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "date" DATE NOT NULL,
    "name" VARCHAR(100) NOT NULL,
    CONSTRAINT "uq_day_off_date_name" UNIQUE ("date", "name")
);

CREATE TABLE "Role" (
    "role_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "role_name" VARCHAR(100) NOT NULL UNIQUE
);

CREATE TABLE "Permission" (
    "permission_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "permission_name" VARCHAR(100) NOT NULL UNIQUE,
    "description" TEXT
);

-- 2. Employees and accounts.
CREATE TABLE "Employee" (
    "employee_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "first_name" VARCHAR(100) NOT NULL,
    "last_name" VARCHAR(100) NOT NULL,
    "work_email" VARCHAR(100) UNIQUE,
    "team_id" INTEGER NOT NULL REFERENCES "Team" ("team_id"),
    "manager_id" INTEGER REFERENCES "Employee" ("employee_id") ON DELETE SET NULL ON UPDATE CASCADE,
    "archived" BOOLEAN NOT NULL DEFAULT FALSE,
    CONSTRAINT "ck_employee_not_own_manager" CHECK (
        "manager_id" IS NULL OR "manager_id" <> "employee_id"
    )
);

CREATE TABLE "Account" (
    "account_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "employee_id" INTEGER NOT NULL UNIQUE REFERENCES "Employee" ("employee_id"),
    "login" VARCHAR(100) NOT NULL UNIQUE,
    "password_hash" VARCHAR(255) NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT TRUE
);

-- N:M relations: many roles per account, many permissions per role.
CREATE TABLE "AccountRole" (
    "account_id" INTEGER NOT NULL REFERENCES "Account" ("account_id") ON DELETE CASCADE ON UPDATE CASCADE,
    "role_id" INTEGER NOT NULL REFERENCES "Role" ("role_id") ON DELETE CASCADE ON UPDATE CASCADE,
    PRIMARY KEY ("account_id", "role_id")
);

CREATE TABLE "RolePermission" (
    "role_id" INTEGER NOT NULL REFERENCES "Role" ("role_id") ON DELETE CASCADE ON UPDATE CASCADE,
    "permission_id" INTEGER NOT NULL REFERENCES "Permission" ("permission_id") ON DELETE CASCADE ON UPDATE CASCADE,
    PRIMARY KEY ("role_id", "permission_id")
);

CREATE TABLE "BranchDayOff" (
    "branch_id" INTEGER NOT NULL REFERENCES "Branch" ("branch_id") ON DELETE CASCADE ON UPDATE CASCADE,
    "day_off_id" INTEGER NOT NULL REFERENCES "DayOff" ("day_off_id") ON DELETE CASCADE ON UPDATE CASCADE,
    PRIMARY KEY ("branch_id", "day_off_id")
);

-- 3. Employment: original terms and subsequent annexes.
CREATE TABLE "Contract" (
    "contract_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "employee_id" INTEGER NOT NULL REFERENCES "Employee" ("employee_id") ON DELETE RESTRICT,
    "contract_type_id" INTEGER NOT NULL REFERENCES "ContractType" ("contract_type_id"),
    "position_id" INTEGER NOT NULL REFERENCES "Position" ("position_id"),
    "conclusion_date" DATE NOT NULL,
    "start_date" DATE NOT NULL,
    "end_date" DATE,
    "employment_fraction" NUMERIC(3,2) NOT NULL,
    CONSTRAINT "ck_contract_dates" CHECK (
        "end_date" IS NULL OR "end_date" >= "start_date"
    ),
    CONSTRAINT "ck_contract_fraction" CHECK (
        "employment_fraction" > 0 AND "employment_fraction" <= 1
    )
);

CREATE TABLE "Annex" (
    "annex_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "contract_id" INTEGER NOT NULL REFERENCES "Contract" ("contract_id"),
    "annex_number" INTEGER NOT NULL,
    "signed_date" DATE NOT NULL,
    "effective_from" DATE NOT NULL,
    "position_id" INTEGER NOT NULL REFERENCES "Position" ("position_id"),
    "employment_fraction" NUMERIC(3,2) NOT NULL,
    "end_date" DATE,
    CONSTRAINT "uq_annex_number" UNIQUE ("contract_id", "annex_number"),
    CONSTRAINT "uq_annex_effective_from" UNIQUE ("contract_id", "effective_from"),
    CONSTRAINT "ck_annex_number" CHECK ("annex_number" > 0),
    CONSTRAINT "ck_annex_fraction" CHECK (
        "employment_fraction" > 0 AND "employment_fraction" <= 1
    ),
    CONSTRAINT "ck_annex_dates" CHECK (
        "end_date" IS NULL OR "end_date" >= "effective_from"
    )
);

-- 4. Schedules, shifts and assignments.
CREATE TABLE "Schedule" (
    "schedule_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "department_id" INTEGER NOT NULL REFERENCES "Department" ("department_id"),
    "period_from" DATE NOT NULL,
    "period_to" DATE NOT NULL,
    "version_number" INTEGER NOT NULL,
    "status" VARCHAR(20) NOT NULL DEFAULT 'draft',
    CONSTRAINT "uq_schedule_version" UNIQUE (
        "department_id", "period_from", "period_to", "version_number"
    ),
    CONSTRAINT "ck_schedule_dates" CHECK ("period_to" >= "period_from"),
    CONSTRAINT "ck_schedule_version" CHECK ("version_number" > 0),
    CONSTRAINT "ck_schedule_status" CHECK (
        "status" IN ('draft', 'published', 'archived')
    )
);

-- At most one published schedule version for exactly the same period.
CREATE UNIQUE INDEX "uq_schedule_one_published_version"
    ON "Schedule" ("department_id", "period_from", "period_to")
    WHERE "status" = 'published';

CREATE TABLE "Shift" (
    "shift_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "schedule_id" INTEGER NOT NULL REFERENCES "Schedule" ("schedule_id"),
    "start_time" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "end_time" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    CONSTRAINT "ck_shift_times" CHECK ("end_time" > "start_time")
);

-- As in the original .sql file, we keep a single-column assignment_id.
-- The pair (shift_id, employee_id) remains a candidate key (UNIQUE),
-- so an employee has at most one assignment and one zone per shift.
-- This is a deliberate implementation decision relative to the logical model in the PDF.
CREATE TABLE "Assignment" (
    "assignment_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "shift_id" INTEGER NOT NULL REFERENCES "Shift" ("shift_id"),
    "employee_id" INTEGER NOT NULL REFERENCES "Employee" ("employee_id") ON DELETE RESTRICT,
    "zone_id" INTEGER NOT NULL REFERENCES "Zone" ("zone_id"),
    CONSTRAINT "uq_assignment_shift_employee" UNIQUE ("shift_id", "employee_id")
);

-- 5. Availability, absences and time registration events.
CREATE TABLE "Availability" (
    "availability_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "employee_id" INTEGER NOT NULL REFERENCES "Employee" ("employee_id"),
    "entered_by_account_id" INTEGER NOT NULL REFERENCES "Account" ("account_id"),
    "available_from" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "available_to" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "available" BOOLEAN NOT NULL,
    CONSTRAINT "ck_availability_times" CHECK ("available_to" > "available_from")
);

CREATE TABLE "Absence" (
    "absence_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "employee_id" INTEGER NOT NULL REFERENCES "Employee" ("employee_id"),
    "absence_type_id" INTEGER NOT NULL REFERENCES "AbsenceType" ("absence_type_id"),
    "entered_by_account_id" INTEGER NOT NULL REFERENCES "Account" ("account_id"),
    "start_date" DATE NOT NULL,
    "end_date" DATE NOT NULL,
    "status" VARCHAR(20) NOT NULL DEFAULT 'registered',
    CONSTRAINT "ck_absence_dates" CHECK ("end_date" >= "start_date"),
    CONSTRAINT "ck_absence_status" CHECK ("status" IN ('registered', 'cancelled'))
);

CREATE TABLE "Registration" (
    "registration_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "employee_id" INTEGER NOT NULL REFERENCES "Employee" ("employee_id") ON DELETE RESTRICT,
    "shift_id" INTEGER REFERENCES "Shift" ("shift_id"),
    "entered_by_account_id" INTEGER NOT NULL REFERENCES "Account" ("account_id"),
    "event_type" VARCHAR(20) NOT NULL,
    "event_time" TIMESTAMP WITHOUT TIME ZONE NOT NULL,
    "entry_time" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "verification_status" VARCHAR(24) NOT NULL DEFAULT 'unverified',
    CONSTRAINT "ck_registration_event_type" CHECK (
        "event_type" IN ('work_start','work_end','break_start','break_end')
    ),
    CONSTRAINT "ck_registration_verification" CHECK (
        "verification_status" IN ('unverified','valid','needs_explanation')
    )
);

-- 6. Operation history (passwords and tokens are never stored in audit data).
CREATE TABLE "Audit" (
    "audit_id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "account_id" INTEGER REFERENCES "Account" ("account_id"),
    "operation_time" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "operation_type" VARCHAR(100) NOT NULL,
    "object_type" VARCHAR(100) NOT NULL,
    "object_id" INTEGER NOT NULL,
    "field_name" VARCHAR(100),
    "value_before" TEXT,
    "value_after" TEXT,
    "change_reason" TEXT
);

COMMIT;

-- After running: \dn, \dt work_time.*, \d work_time."Assignment" (psql commands).
-- NOTE: manager cycles, time collisions, zone capacity, schedule versioning
--       and full audit go beyond CHECK/PK/FK; they require additional
--       functions/triggers or application logic.
